use crate::native_decoding::{NativeDecodeControl,NativeForwardedDecodeControl,NativeDecodeAllocation,NativeDecodeRetirementRecipient};
use crate::{RetainedCloneGrant,retirement::controlled::ControlledRetirement};
use crate::allocation_testing::observe_retirement_allocations as observe;
use std::sync::atomic::{AtomicUsize,Ordering};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn grant(law:&serde_json::Value)->RetainedCloneGrant{serde_json::from_value(law["grant"].clone()).unwrap()}
fn close(original:String,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant){let bytes=original.capacity();let(result,heap)=observe(||ControlledRetirement::new(original));assert_eq!(heap,(0,0));let mut owner=result.map_err(|(error,_)|error).unwrap();let(mut born,mut released)=(0,0);for _ in 0..4096{if owner.terminal_is_empty(){let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));assert_eq!(bytes+born,released);return}let capacity=owner.next_capacity_byte_demand(g.maximum_copy_bytes).unwrap();assert!(capacity<=g.maximum_capacity_bytes);assert!(owner.next_copy_byte_demand().unwrap()<=g.maximum_copy_bytes);assert!(owner.next_release_byte_demand().unwrap()<=g.maximum_release_bytes);assert!(owner.next_depth_demand().unwrap()<=g.maximum_depth);control.charge(capacity).unwrap();let(step,heap)=observe(||owner.step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;}panic!("original ledger output retirement frontier")}
#[test]
fn original_decode_ledger_local_pause_resume_preserves_receipt_and_new_callback(){
 let law=fixture();let maximum=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let calls=AtomicUsize::new(0);let mut first=|_|{calls.fetch_add(1,Ordering::SeqCst);true};let mut original=NativeDecodeControl::new(maximum,&mut first);let ledger=original.ledger_identity();let(text,heap)=observe(||original.copy_text(law["text"].as_str().unwrap()).unwrap());assert_eq!(heap,(law["textBytes"].as_u64().unwrap()as usize,0));let pointer=text.as_ptr();let owned=original.owned_bytes();let receipt=original.pause().unwrap();let next_calls=AtomicUsize::new(0);let mut next=|_|{next_calls.fetch_add(1,Ordering::SeqCst);true};let(resumed,heap)=observe(||NativeDecodeControl::resume(receipt,&mut next).unwrap());assert_eq!(heap,(0,0));let mut resumed=resumed;assert_eq!(resumed.ledger_identity(),ledger);assert_eq!(resumed.owned_bytes(),owned);assert_eq!(resumed.maximum_bytes(),maximum);let before=calls.load(Ordering::SeqCst);resumed.checkpoint().unwrap();assert_eq!(calls.load(Ordering::SeqCst),before);assert_eq!(next_calls.load(Ordering::SeqCst),1);let mut foreign_callback=|_|true;let foreign=NativeDecodeControl::new(maximum,&mut foreign_callback);assert_ne!(foreign.ledger_identity(),ledger);assert_eq!(foreign.owned_bytes(),0);assert_eq!(text.as_ptr(),pointer);close(text,&mut resumed,grant(&law));eprintln!("[DEBUG] Original local receipt moves its actual ledger and cumulative bytes across callback rebind; fresh same-ceiling control is foreign");
}
#[test]
fn original_decode_ledger_local_recipient_detach_bind_preserves_lineage_and_refusal(){
 let law=fixture();let maximum=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let mut first=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut original=NativeDecodeControl::new(maximum,&mut first);original.install_retirement_recipient(&mut recipient).unwrap();let witness=(original.ledger_identity(),original.retirement_recipient_identity());let(text,heap)=observe(||original.copy_text(law["text"].as_str().unwrap()).unwrap());assert_eq!(heap,(law["textBytes"].as_u64().unwrap()as usize,0));let owned=original.owned_bytes();let(detached,_)=original.pause_with_retirement().unwrap().detach();let mut foreign=NativeDecodeRetirementRecipient::new();let(result,heap)=observe(||detached.bind(&mut foreign));assert_eq!(heap,(0,0));let(error,detached)=match result{Err(error)=>error,Ok(_)=>panic!("foreign original recipient")};assert_eq!(error.kind,crate::ValueRefusalKind::OwnershipLimit);assert_eq!(detached.owned_bytes(),owned);let mut receipt=detached.bind(&mut recipient).map_err(|(error,_)|error).unwrap();let mut canceled=|_|false;let(result,heap)=observe(||receipt.decode(&mut canceled,|loan|{assert_eq!((loan.ledger_identity(),loan.retirement_recipient_identity()),witness);loan.checkpoint()}));assert_eq!(heap,(0,0));assert_eq!(result.unwrap_err().kind,crate::ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),owned);let mut next=|_|true;receipt.decode(&mut next,|loan|{assert_eq!((loan.ledger_identity(),loan.retirement_recipient_identity()),witness);close(text,loan,grant(&law));Ok(())}).unwrap();drop(receipt);assert!(crate::ErasedSnapshotRetirement::terminal_is_empty(&recipient));eprintln!("[DEBUG] Original local recipient detachment refuses replacement without consuming receipt; canceled hop and accepted supplier rebind preserve actual ledger");
}
#[test]
fn original_decode_ledger_forwarded_pause_resume_detach_rebind_preserves_original_ports(){
 let law=fixture();let maximum=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let admitted=AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,admitted.load(Ordering::SeqCst));assert_eq!(request.maximum_bytes,maximum);assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);admitted.store(request.next_owned_bytes,Ordering::SeqCst);Ok(())};let mut first=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut original=NativeDecodeControl::new_forwarded(maximum,&mut first,&mut allocation);original.install_retirement_recipient(&mut recipient).unwrap();let witness=(original.ledger_identity(),original.retirement_recipient_identity());let(text,heap)=observe(||original.copy_text(law["text"].as_str().unwrap()).unwrap());assert_eq!(heap,(law["textBytes"].as_u64().unwrap()as usize,0));let owned=original.owned_bytes();let receipt=original.pause().unwrap();let mut next=|_|true;let(resumed,heap)=observe(||NativeForwardedDecodeControl::resume(receipt,&mut next).unwrap());assert_eq!(heap,(0,0));assert_eq!((resumed.ledger_identity(),resumed.retirement_recipient_identity()),witness);let detached=resumed.detach().map_err(|(error,_)|error).unwrap();let mut foreign=NativeDecodeRetirementRecipient::new();let mut third=|_|true;let(result,heap)=observe(||NativeForwardedDecodeControl::rebind(detached,&mut third,&mut allocation,&mut foreign));assert_eq!(heap,(0,0));let(error,detached)=match result{Err(error)=>error,Ok(_)=>panic!("foreign forwarded recipient")};assert_eq!(error.kind,crate::ValueRefusalKind::InvariantViolated);assert_eq!(detached.owned_bytes(),owned);let mut fourth=|_|true;let(result,heap)=observe(||NativeForwardedDecodeControl::rebind(detached,&mut fourth,&mut allocation,&mut recipient));assert_eq!(heap,(0,0));let mut resumed=result.map_err(|(error,_)|error).unwrap();assert_eq!((resumed.ledger_identity(),resumed.retirement_recipient_identity()),witness);close(text,&mut resumed,grant(&law));assert_eq!(resumed.owned_bytes(),admitted.load(Ordering::SeqCst));drop(resumed);assert!(crate::ErasedSnapshotRetirement::terminal_is_empty(&recipient));eprintln!("[DEBUG] Original forwarded pause/resume/detach/rebind retains actual ledger, original allocator/recipient, cumulative admission and paid physical output close");
}
#[test]
fn original_decode_forwarded_recipient_move_preserves_consuming_lineage_and_foreign_refusal(){
 let law=fixture();let maximum=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let admitted=AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,admitted.load(Ordering::SeqCst));assert_eq!(request.maximum_bytes,maximum);admitted.store(request.next_owned_bytes,Ordering::SeqCst);Ok(())};let mut callback=|_|true;let mut slots=[Some(NativeDecodeRetirementRecipient::new()),None];let mut control=NativeDecodeControl::new_forwarded(maximum,&mut callback,&mut allocation);control.install_retirement_recipient(slots[0].as_mut().unwrap()).unwrap();let witness=(control.ledger_identity(),control.retirement_recipient_identity());let(text,heap)=observe(||control.copy_text(law["text"].as_str().unwrap()).unwrap());assert_eq!(heap,(law["textBytes"].as_u64().unwrap()as usize,0));let detached=control.detach().map_err(|(error,_)|error).unwrap();let((),heap)=observe(||slots[1]=slots[0].take());assert_eq!(heap,(0,0));let mut foreign=NativeDecodeRetirementRecipient::new();let mut next=|_|true;let(result,heap)=observe(||NativeForwardedDecodeControl::rebind(detached,&mut next,&mut allocation,&mut foreign));assert_eq!(heap,(0,0));let(error,detached)=match result{Err(value)=>value,Ok(_)=>panic!("foreign recipient accepted original moved receipt")};assert_eq!(error.kind,crate::ValueRefusalKind::InvariantViolated);let(result,heap)=observe(||NativeForwardedDecodeControl::rebind(detached,&mut next,&mut allocation,slots[1].as_mut().unwrap()));assert_eq!(heap,(0,0));let mut control=result.map_err(|(error,_)|error).unwrap();assert_eq!((control.ledger_identity(),control.retirement_recipient_identity()),witness);assert_eq!(control.owned_bytes(),admitted.load(Ordering::SeqCst));close(text,&mut control,grant(&law));drop(control);assert!(crate::ErasedSnapshotRetirement::terminal_is_empty(slots[1].as_ref().unwrap()));assert!(slots[0].is_none());eprintln!("[DEBUG] Original forwarded recipient physically moves while its consuming ledger/recipient identity and cumulative original allocator stay intact; foreign receiver refused without consuming authority");
}
